CREATE TABLE consistency.dependency_nodes(node_id text PRIMARY KEY,node_kind text NOT NULL CHECK(node_kind IN('CANONICAL_FACT_VERSION','RULE_VERSION','RULESET_VERSION','TEMPORAL_ALIGNMENT','CONSISTENCY_RESULT','POLICY_VERSION')),object_id text NOT NULL,object_version text NOT NULL,node_checksum text NOT NULL CHECK(node_checksum~'^[0-9a-f]{64}$'),bounded_metadata jsonb NOT NULL CHECK(jsonb_typeof(bounded_metadata)='array'),created_at timestamptz NOT NULL,UNIQUE(node_kind,object_id,object_version));
CREATE TABLE consistency.dependency_edges(edge_id text PRIMARY KEY,edge_kind text NOT NULL CHECK(edge_kind IN('FACT_INPUT_TO_RULE','RULE_DEPENDS_ON_RULE','POLICY_GOVERNS_RULE','FACT_USED_BY_ALIGNMENT','ALIGNMENT_USED_BY_RESULT','RULE_PRODUCED_RESULT','FACT_USED_BY_RESULT','RESULT_DERIVED_FROM_RESULT','RESULT_SUPERSEDES_RESULT')),from_node_id text NOT NULL REFERENCES consistency.dependency_nodes(node_id),to_node_id text NOT NULL REFERENCES consistency.dependency_nodes(node_id),policy_version text NOT NULL,edge_checksum text NOT NULL CHECK(edge_checksum~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL,CHECK(from_node_id<>to_node_id));
CREATE TABLE consistency.dependency_edge_conflicts(conflict_id text PRIMARY KEY,edge_id text NOT NULL,existing_checksum text NOT NULL,incoming_checksum text NOT NULL,detected_at timestamptz NOT NULL,CHECK(existing_checksum<>incoming_checksum),UNIQUE(edge_id,existing_checksum,incoming_checksum));
CREATE TABLE consistency.dependency_snapshots(snapshot_id text PRIMARY KEY,schema_version text NOT NULL,complete boolean NOT NULL,missing_node_ids text[] NOT NULL,snapshot_checksum text NOT NULL CHECK(snapshot_checksum~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL);
CREATE TABLE consistency.dependency_snapshot_nodes(snapshot_id text NOT NULL REFERENCES consistency.dependency_snapshots(snapshot_id),node_id text NOT NULL REFERENCES consistency.dependency_nodes(node_id),PRIMARY KEY(snapshot_id,node_id));
CREATE TABLE consistency.dependency_snapshot_edges(snapshot_id text NOT NULL REFERENCES consistency.dependency_snapshots(snapshot_id),edge_id text NOT NULL REFERENCES consistency.dependency_edges(edge_id),PRIMARY KEY(snapshot_id,edge_id));
CREATE TABLE consistency.recompute_requests_v2(request_id text PRIMARY KEY,request_identity text NOT NULL UNIQUE,triggering_node_id text NOT NULL REFERENCES consistency.dependency_nodes(node_id),impact_id text NOT NULL,snapshot_id text NOT NULL REFERENCES consistency.dependency_snapshots(snapshot_id),event_time_start timestamptz NOT NULL,event_time_end timestamptz NOT NULL,knowledge_mode text NOT NULL CHECK(knowledge_mode IN('AS_KNOWN_THEN','LATEST_CORRECTED','RETROSPECTIVE')),knowledge_time_cutoff timestamptz NOT NULL,recompute_policy_version text NOT NULL,target_result_ids text[] NOT NULL,request_checksum text NOT NULL CHECK(request_checksum~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL,CHECK(event_time_end>event_time_start));
CREATE TABLE consistency.recompute_conflicts(conflict_id text PRIMARY KEY,request_id text NOT NULL,existing_checksum text NOT NULL,incoming_checksum text NOT NULL,detected_at timestamptz NOT NULL,CHECK(existing_checksum<>incoming_checksum),UNIQUE(request_id,existing_checksum,incoming_checksum));
CREATE TABLE consistency.recompute_plans(plan_id text PRIMARY KEY,request_id text NOT NULL UNIQUE REFERENCES consistency.recompute_requests_v2(request_id),snapshot_id text NOT NULL REFERENCES consistency.dependency_snapshots(snapshot_id),skipped_node_ids text[] NOT NULL,blocking_reasons text[] NOT NULL,plan_checksum text NOT NULL CHECK(plan_checksum~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL);
CREATE TABLE consistency.recompute_plan_steps(step_id text PRIMARY KEY,plan_id text NOT NULL REFERENCES consistency.recompute_plans(plan_id),ordinal integer NOT NULL CHECK(ordinal>=0),rule_node_id text NOT NULL REFERENCES consistency.dependency_nodes(node_id),dependency_step_ids text[] NOT NULL,exact_fact_node_ids text[] NOT NULL,policy_node_ids text[] NOT NULL,prior_result_node_ids text[] NOT NULL,step_checksum text NOT NULL CHECK(step_checksum~'^[0-9a-f]{64}$'),UNIQUE(plan_id,ordinal));
CREATE TABLE consistency.recompute_step_claims(step_id text PRIMARY KEY REFERENCES consistency.recompute_plan_steps(step_id),worker_id text NOT NULL,claimed_at timestamptz NOT NULL);
CREATE TABLE consistency.recompute_step_events(event_id text PRIMARY KEY,step_id text NOT NULL REFERENCES consistency.recompute_plan_steps(step_id),outcome text NOT NULL CHECK(outcome IN('COMPLETED','FAILED','CANCELLED','BLOCKED_DEPENDENCY')),result_id text,reason_codes text[] NOT NULL,event_checksum text NOT NULL CHECK(event_checksum~'^[0-9a-f]{64}$'),occurred_at timestamptz NOT NULL,UNIQUE(step_id,outcome));
CREATE UNIQUE INDEX recompute_step_one_terminal_idx ON consistency.recompute_step_events(step_id) WHERE outcome IN('COMPLETED','FAILED','CANCELLED');
CREATE TABLE consistency.result_dependency_links(result_id text NOT NULL REFERENCES consistency.immutable_results(result_id),snapshot_id text NOT NULL REFERENCES consistency.dependency_snapshots(snapshot_id),plan_id text NOT NULL REFERENCES consistency.recompute_plans(plan_id),step_id text NOT NULL REFERENCES consistency.recompute_plan_steps(step_id),created_at timestamptz NOT NULL,PRIMARY KEY(result_id,plan_id,step_id));
CREATE TABLE consistency.result_selection_decisions(decision_id text PRIMARY KEY,selected_result_id text,rejected_result_ids text[] NOT NULL,reason_codes text[] NOT NULL,policy_version text NOT NULL,knowledge_mode text NOT NULL CHECK(knowledge_mode IN('AS_KNOWN_THEN','LATEST_CORRECTED','RETROSPECTIVE')),knowledge_time_cutoff timestamptz NOT NULL,decision_checksum text NOT NULL CHECK(decision_checksum~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL);
CREATE INDEX dependency_edges_reverse_idx ON consistency.dependency_edges(from_node_id,to_node_id,edge_kind);
CREATE INDEX dependency_edges_forward_idx ON consistency.dependency_edges(to_node_id,from_node_id,edge_kind);
CREATE INDEX recompute_steps_ready_idx ON consistency.recompute_plan_steps(plan_id,ordinal,step_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['dependency_nodes','dependency_edges','dependency_edge_conflicts','dependency_snapshots','dependency_snapshot_nodes','dependency_snapshot_edges','recompute_requests_v2','recompute_conflicts','recompute_plans','recompute_plan_steps','recompute_step_claims','recompute_step_events','result_dependency_links','result_selection_decisions'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON consistency.%I FOR EACH ROW EXECUTE FUNCTION consistency.reject_immutable_result_mutation()',t || '_no_mutation',t); END LOOP; END $$;
